<?php $page_title='Semua Produk'; include 'partials/header.php';
$q=$_GET['q']??'';$category=(int)($_GET['category']??0);$sort=$_GET['sort']??'new';
$where=[];$types='';$vals=[];if($q!==''){$where[]='p.name LIKE ?';$types.='s';$vals[]='%'.$q.'%';}if($category){$where[]='p.category_id=?';$types.='i';$vals[]=$category;}
$order=$sort==='low'?'p.price ASC':($sort==='high'?'p.price DESC':'p.id DESC');$sql='SELECT p.* FROM products p'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY '.$order;$stmt=$conn->prepare($sql);if($vals){$stmt->bind_param($types,...$vals);} $stmt->execute();$products=$stmt->get_result();$cats=$conn->query('SELECT * FROM categories ORDER BY name'); ?>
<section class="section container"><div class="section-head"><div><span class="muted">Katalog</span><h2>Temukan produk favoritmu</h2></div></div><form class="search-panel"><input class="input" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Cari produk..."><select name="category"><option value="0">Semua kategori</option><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$category==$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endwhile;?></select><select name="sort"><option value="new">Terbaru</option><option value="low" <?=$sort==='low'?'selected':''?>>Harga termurah</option><option value="high" <?=$sort==='high'?'selected':''?>>Harga tertinggi</option></select><button class="btn">Cari</button></form><div class="product-grid"><?php while($p=$products->fetch_assoc()) include 'partials/product_card.php';?></div></section><?php include 'partials/footer.php';?>
